"use client";

import Image from "next/image";
import Link from "next/link";
import { useState } from "react";
import { Post } from "@/types/blog";

const FALLBACK_THUMBNAIL = "https://picsum.photos/seed/tistory/760/420";

interface HeroCarouselProps {
  posts: Post[];
}

export default function HeroCarousel({ posts }: HeroCarouselProps) {
  const [index, setIndex] = useState(0);
  const post = posts[index];

  if (!post) return null;

  return (
    <div className="hero">
      <Link href={`/posts/${post.slug}`} className="hero-image">
        <Image
          src={post.thumbnail ?? FALLBACK_THUMBNAIL}
          alt={post.title}
          fill
          sizes="(max-width: 900px) 100vw, 760px"
          priority
        />
        <span className="hero-badge">오늘의 티스토리</span>
        <div className="hero-caption">
          <p className="hero-title">&ldquo; {post.title}</p>
          <div className="hero-author">
            <span className="hero-avatar" />
            <span>{post.author}</span>
          </div>
        </div>
      </Link>
      <div className="hero-dots">
        {posts.map((p, i) => (
          <button
            key={p.id}
            type="button"
            aria-label={`${i + 1}번째 슬라이드`}
            className={i === index ? "hero-dot hero-dot--active" : "hero-dot"}
            onClick={() => setIndex(i)}
          />
        ))}
      </div>
    </div>
  );
}